D = {}
for blk in (M, B, L, F):
    for line in blk.strip().split('\n'):
        for kv in line.split(';'):
            if '=' in kv:
                k, v = kv.split('=', 1); D[k.strip()] = v.strip()
ORD = {'First': 1, 'Second': 2, 'Third': 3, 'Fourth': 4, 'Fifth': 5, 'Sixth': 6, 'Seventh': 7, 'Eighth': 8, 'Ninth': 9, 'Tenth': 10, 'Eleventh': 11, 'Twelfth': 12}
TOOTH = {'canine': '犬齒', 'first molar tooth': '第一大臼齒', 'second molar tooth': '第二大臼齒', 'first premolar': '第一小臼齒', 'second premolar': '第二小臼齒', 'lateral incisor': '側門齒', 'medial incisor': '正中門齒'}
SEG = {'C': '頸椎', 'T': '胸椎', 'L': '腰椎', 'S': '薦椎'}
def key(n): return n.replace(' muscle', '')
def zh(name):
    k = key(name)
    if k in D: return D[k]
    m = re.match(r'^(\w+) rib$', k)
    if m and m.group(1) in ORD: return f'第 {ORD[m.group(1)]} 肋骨'
    m = re.match(r'^Costal cartilage of (\w+) rib$', k)
    if m and m.group(1).capitalize() in ORD: return f'第 {ORD[m.group(1).capitalize()]} 肋軟骨'
    m = re.match(r'^(\w+) (metacarpal|metatarsal) bone$', k)
    if m and m.group(1) in ORD: return f'第 {ORD[m.group(1)]} ' + ('掌骨' if m.group(2) == 'metacarpal' else '蹠骨')
    m = re.match(r'^(Distal|Middle|Proximal) phalanx of (\w+) finger of (foot|hand)$', k)
    if m and m.group(2).capitalize() in ORD:
        seg = {'Distal': '遠節', 'Middle': '中節', 'Proximal': '近節'}[m.group(1)]; d = '趾' if m.group(3) == 'foot' else '指'
        return f'第 {ORD[m.group(2).capitalize()]} {d}{seg}{d}骨'
    m = re.match(r'^Vertebra ([CTL])(\d+)$', k)
    if m: return f'第 {m.group(2)} {SEG[m.group(1)]}（{m.group(1)}{m.group(2)}）'
    m = re.match(r'^(Intervertebral disc|Nucleus pulposus) ([CTLS]\d+-[CTLS]\d+)$', k)
    if m: return ('椎間盤 ' if m.group(1).startswith('Inter') else '髓核 ') + m.group(2)
    m = re.match(r'^(Upper|Lower) (.+)$', k)
    if m and m.group(2) in TOOTH: return ('上' if m.group(1) == 'Upper' else '下') + TOOTH[m.group(2)]
    return ''
if __name__ == '__main__':
    names = json.load(open(sys.argv[1], encoding='utf8')); out = {}
    for n in names:
        n2 = re.sub(r'^\((.*)\)$', r'\1', n); z = zh(n) or zh(n2)
        if z: out[n] = z; out[n2] = z
    json.dump(out, open(sys.argv[2], 'w', encoding='utf8'), ensure_ascii=False)
    miss = [n for n in names if n not in out]
    print('names', len(names), 'translated', len(names) - len(miss), 'missing', len(miss)); print('; '.join(miss[:80]))
